 content=crumbs([('Каталог','/catalog/'),(CATS[p['category']][0],'/category/'+p['category']+'/'),(p['sku'],None)])+f'''<div class="wrap"><article itemscope itemtype="https://schema.org/Product" itemid="{e(base+path)}#product"><section class="product-detail"><div><div class="detail-photo">{picture(p,True)}</div></div><div><div class="brand-label" itemprop="brand">{e(p['brand'])}</div><h1 itemprop="name">{e(p_name)}</h1><div class="detail-sku">Артикул: <strong itemprop="sku">{p['sku']}</strong></div><div itemprop="offers" itemscope itemtype="https://schema.org/Offer" itemid="{e(base+path)}#offer"><meta itemprop="price" content="{p['price']}"><meta itemprop="priceCurrency" content="RUB"><link itemprop="url" href="{e(base+path)}"><div class="detail-price">{money(p['price'])} ₽</div>{stock}<p class="price-note">Комплектность и условия доставки согласуются при оформлении заказа.</p></div><button class="btn" data-add="{p['id']}">{icon('plus')} Добавить в корзину</button><dl class="specs"><div><dt>Бренд</dt><dd><a href="/brands/{next(k for k,v in BRANDS.items() if v==p['brand'])}/">{e(p['brand'])}</a></dd></div><div><dt>Артикул</dt><dd>{p['sku']}</dd></div><div><dt>Раздел</dt><dd><a href="/category/{p['category']}/">{CATS[p['category']][0]}</a></dd></div><div><dt>Регион продаж</dt><dd>Вся Россия</dd></div><div><dt>Условия поставки</dt><dd>По согласованию</dd></div></dl><nav class="product-anchor-nav" aria-label="Информация о товаре"><a href="#description">Описание</a><a href="#part-numbers">Артикулы</a><a href="#order-details">Как заказать</a></nav></div></section><section class="product-description" id="description"><h2>О детали</h2><div itemprop="description"><p>{e(p['copy'][0])}</p> <p>{e(p['copy'][1])}</p></div></section><section class="product-description" id="part-numbers"><h2>Артикулы для проверки</h2><div><p>Сверьте номер на вашей детали с обозначениями в карточке. Дополнительные номера помогают поиску; их связь, взаимозаменяемость и применимость необходимо подтвердить перед заказом.</p><div class="code-list">{codes}</div></div></section></article><section class="product-description" id="order-details"><h2>Как заказать</h2><div><p>Добавьте позицию в корзину и укажите количество. Для проверки подбора сообщите модель техники, модель и серийный номер двигателя, а также номер установленного узла. Если состав комплекта неясен, укажите это в комментарии.</p><p>Цена в карточке указана в рублях. Актуальную цену, наличие, состояние детали, комплектность и документы нужно согласовать до покупки. Для расчёта доставки по России добавьте город получения.</p><p><a class="text-link" href="/delivery/">Доставка и оплата {icon('arrow')}</a></p></div></section><section class="section product-reading"><div class="section-heading"><h2>Полезно перед заказом</h2></div><div class="article-grid">{''.join(article_card(a) for a in articles[:2])}</div></section><section class="section"><div class="section-heading"><h2>В этом же разделе</h2><a class="text-link" href="/category/{p['category']}/">Все позиции {icon('arrow')}</a></div><div class="grid">{''.join(card(x)for x in related)}</div></section></div>'''+contact()
